1 | import { Message, LLMProvider } from "../providers/base";
2 | import { ScopedLogger } from "../util/log";
3 | 
4 | export class Compaction {
5 |   private readonly maxTokens: number;
6 |   private readonly maxOutputTokens: number;
7 |   private readonly triggerRatio = 0.15; // 92% 触发压缩
8 |   private readonly targetRatio = 0.75; // 压缩到 75% 停止
9 | 
10 |   // 经验系数：中文 1:1, 英文 4:1
11 |   private readonly WEIGHT_ZH = 1.0;
12 |   private readonly WEIGHT_EN = 0.25;
13 |   logger: ScopedLogger;
14 |   lastSummaryMessage: Message | null;
15 |   private readonly llmProvider: LLMProvider;
16 | 
17 |   constructor(config: { maxTokens: number; maxOutputTokens: number; llmProvider: LLMProvider }) {
18 |     this.maxTokens = config.maxTokens;
19 |     this.maxOutputTokens = config.maxOutputTokens;
20 |     this.llmProvider = config.llmProvider;
21 |     this.logger = new ScopedLogger("Compaction");
22 |     this.lastSummaryMessage = null;
23 | 
24 |   }
25 | 
26 |    getToken(history: Message[]){
27 |     const totalUsed = this.calculateTotalUsage(history);
28 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
29 | 
30 |     return {
31 |       totalUsed,
32 |       usableLimit
33 |     }
34 |   }
35 | 
36 |   /**
37 |    * 核心入口：检查并执行压缩
38 |    * @param history 原始历史记录
39 |    * @param summarizer 外部注入的 LLM 摘要执行器
40 |    */
41 |   async compact(history: Message[]): Promise<{
42 |     isCompacted: boolean,
43 |     summaryMessage: Message | null,
44 |     list: Message[]
45 |   }> {
46 |     const totalUsed = this.calculateTotalUsage(history);
47 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
48 |     const KEEP_RECENT_COUNT = 6;
49 |     // 如果没达到 92% 的阈值，直接返回原数据
50 |     if (totalUsed < usableLimit * this.triggerRatio || history.length <= KEEP_RECENT_COUNT) {
51 |       return {
52 |         isCompacted: false,
53 |         summaryMessage: null,
54 |         list: history
55 |       };
56 |     }
57 | 
58 | 
59 | 
60 |     this.logger.info(
61 |       `[Compaction] 触发压缩。当前 Token: ${totalUsed}, 阈值: ${Math.floor(usableLimit * this.triggerRatio)}`
62 |     );
63 | 
64 | 
65 |     const activeMessages = history.slice(-KEEP_RECENT_COUNT); // 保护区
66 |     let pendingMessages = history.slice(0, -KEEP_RECENT_COUNT); // 待压缩区
67 | 
68 |     // 3. 提取之前的摘要（如果存在）
69 |     let previousSummary = "";
70 |     if (pendingMessages.length > 0 && pendingMessages[0].type === "summary") {
71 |       previousSummary = pendingMessages[0].content;
72 |       pendingMessages = pendingMessages.slice(1);
73 |     }
74 | 
75 |     // 4. 将待压缩的消息序列化为文本
76 |     // 特别处理：将 tool 消息与其 result 格式化，方便 LLM 理解
77 |     const textToSummarize = pendingMessages
78 |       .map((m) => {
79 |         const prefix = m.type ? `[${m.role}:${m.type}]` : `[${m.role}]`;
80 |         // 如果内容过长（如巨大的代码输出），在摘要前进行初步截断
81 |         const content =
82 |           m.content.length > 2000
83 |             ? m.content.slice(0, 1000) + "...(省略)..."
84 |             : m.content;
85 |         return `${prefix}: ${content}`;
86 |       })
87 |       .join("\n");
88 | 
89 |     // 5. 执行异步摘要
90 |     try {
91 |       const newSummaryContent = await this.summarizer(
92 |         textToSummarize,
93 |         previousSummary,
94 |       );
95 | 
96 |       const summaryMessage: Message = {
97 |         role: "system",
98 |         type: "summary",
99 |         content: `[Historical Memory Snapshot]:\n${newSummaryContent}`,
100 |       };
101 | 
102 |       // 6. 重组历史
103 |       const newHistory = [summaryMessage, ...activeMessages];
104 | 
105 |       // 7. 递归检查：如果压缩后还是超标（极端情况），继续压缩
106 |       // if (
107 |       //   this.calculateTotalUsage(newHistory) >
108 |       //   usableLimit * this.targetRatio
109 |       // ) {
110 |       //   // 如果单条摘要+保护区还是太大，可以考虑减少保护区数量
111 |       //   return newHistory.slice(-KEEP_RECENT_COUNT);
112 |       // }
113 | 
114 |       return {
115 |         isCompacted: true,
116 |         summaryMessage,
117 |         list: newHistory
118 |       };
119 |     } catch (error) {
120 |       const errorMsg = error instanceof Error ? error.message : String(error);
121 |       this.logger.error(`[Compaction] 摘要生成失败: ${errorMsg}`);
122 |       return {
123 |         isCompacted: true,
124 |         summaryMessage: null,
125 |         list: history.slice(0, history.length - KEEP_RECENT_COUNT)
126 |       };
127 |     }
128 |   }
129 | 
130 |   /**
131 |    * 计算整个对话数组的 Token 用量
132 |    */
133 |   public calculateTotalUsage(messages: Message[]): number {
134 |     return messages.reduce((acc, m) => {
135 |       // 每条消息基础开销 4 tokens (role, name, newline)
136 |       return acc + this.estimate(m.content) + 4;
137 |     }, 0);
138 |   }
139 | 
140 |   /**
141 |    * 估算单段文本的 Token
142 |    */
143 |   private estimate(text: string): number {
144 |     if (!text) return 0;
145 |     // 匹配 CJK 字符（中日韩）
146 |     const chineseChars = text.match(/[\u4e00-\u9fa5]/g)?.length || 0;
147 |     const otherChars = text.length - chineseChars;
148 |     return Math.ceil(
149 |       chineseChars * this.WEIGHT_ZH + otherChars * this.WEIGHT_EN,
150 |     );
151 |   }
152 | 
153 |   async summarizer(textToSummarize: string, previousSummary?: string) {
154 |     const spinner = this.logger.spinner("上下文压缩...");
155 | 
156 |     try {
157 |       const llmResponse = await this.llmProvider.generate(
158 |         [
159 |           {
160 |             role: "user",
161 |             content: `You are an expert conversation compressor. Compress the conversation history into a structured summary organized in the following 8 sections:
162 | 1. **Primary Request and Intent**: What is the user's core goal?
163 | 2. **Key Technical Concepts**: Frameworks, libraries, tech stacks, etc., involved in the conversation.
164 | 3. **Files and Code Sections**: All file paths mentioned or modified.
165 | 4. **Errors and Fixes**: Record error messages encountered and their solutions.
166 | 5. **Problem Solving**: The thought process and decision path for solving the problem.
167 | 6. **All User Messages**: Preserve key instructions and feedback from the user.
168 | 7. **Pending Tasks**: Work items that remain unfinished.
169 | 8. **Current Work**: The progress at the point the conversation was interrupted.
170 | 
171 | <previous_summary>
172 |  ${previousSummary}
173 | </previous_summary>
174 | 
175 | <current_mesage_history>
176 | ${textToSummarize}
177 | </current_mesage_history>
178 | 
179 |   ## Requirements:
180 | - Maintain high density and accuracy of information
181 | - Highlight key technical decisions and solutions
182 | - Ensure continuity of context
183 | - Retain all important file paths
184 | - Use concise English expression`,
185 |           },
186 |         ],
187 |         {
188 |           model: "deepseek-chat",
189 |           max_tokens: 8000,
190 |           temperature: 0.3,
191 |         },
192 |       );
193 |       spinner.succeed("上下文压缩成功");
194 |       return llmResponse?.content || '';
195 |     } catch (error: any) {
196 |       this.logger.error(error.toString());
197 | 
198 |       spinner.fail("上下文压缩失败");
199 |     }
200 |   }
201 | }
