2 | import { LLMProvider, Message } from "../providers/base";
3 | import fs, { mkdir } from 'node:fs/promises';
4 | import { Compaction } from "./compaction";
5 | 
6 | export class SessionManager {
7 |   id: string;
8 |   messageList: Message[];
9 |   sessionPath: string;
10 |   private saveQueue: Promise<void> = Promise.resolve();
11 |   maxOutputTokens: number;
12 |   maxTokens: number;
13 |   llmProvider: LLMProvider;
14 | 
15 |   constructor({
16 |     sessionId,
17 |     llmProvider
18 |   }: {
19 |     sessionId: string,
20 |     llmProvider: LLMProvider
21 |   }) {
22 |     this.id = sessionId;
23 |     this.messageList = []
24 |     this.sessionPath = path.join('.memory', this.id);
25 |     this.maxOutputTokens = llmProvider.maxOutputTokens;
26 |     this.maxTokens = llmProvider.maxTokens
27 |     this.llmProvider = llmProvider;
28 |   }
29 | 
30 |   async init() {
31 |     await mkdir(this.sessionPath, { recursive: true });
32 |     try {
33 |       const filePath = path.join(this.sessionPath, 'messages.json');
34 |       const stats = await fs.stat(filePath);
35 | 
36 |       if (stats.isFile()) {
37 |         const content = await fs.readFile(filePath, {
38 |           encoding: 'utf-8'
39 |         });
40 | 
41 |         const messageList = JSON.parse(content.trim());
42 |         if (messageList.length) {
43 |           this.messageList = messageList;
44 |         }
45 |       }
46 |     } catch (err) {
47 |       // 文件不存在或其他错误，忽略
48 |     }
49 |   }
50 | 
51 |   addMessage(message: Message) {
52 |     this.messageList.push(message);
53 |     // Fire-and-forget：加入保存队列，不阻塞调用方
54 |     this.save(message);
55 |   }
56 | 
57 |   async compact() {
58 |     const compaction = new Compaction({
59 |       maxOutputTokens: this.maxOutputTokens,
60 |       maxTokens: this.maxTokens,
61 |       llmProvider: this.llmProvider
62 |     });
63 | 
64 |     const token = compaction.getToken(this.messageList);
65 |     console.log(`TOKEN: ${token.totalUsed}/${token.usableLimit}\n`);
66 |     
67 |     return await compaction.compact(this.messageList);
68 |   }
69 | 
70 |   private save(message: Message) {
71 |     // 使用 Promise 链确保保存顺序，防止竞态条件
72 |     this.saveQueue = this.saveQueue.then(async () => {
73 |       try {
74 |         await fs.writeFile(
75 |           path.join(this.sessionPath, 'messages.json'),
76 |           JSON.stringify(this.messageList, null, 2)
77 |         );
78 |         await fs.appendFile(
79 |           path.join(this.sessionPath, 'cache.md'),
80 |           `\`\`\`\n${JSON.stringify(message, null, 2)}\n\`\`\`\n`,
81 |           { flag: 'a' }
82 |         );
83 |       } catch (err) {
84 |         console.error('Session save error:', err);
85 |       }
86 |     });
87 |   }
88 | 
89 |   async getMessages(): Promise<Message[]> {
90 |     // if (this.messageList.length < 10) {
91 |     //   return this.messageList;
92 |     // }
93 | 
94 |     const result = await this.compact();
95 | 
96 |     this.messageList = result.list;
97 | 
98 |     if (result.isCompacted && result.summaryMessage) {
99 |       this.save(result.summaryMessage)
100 |     }
101 | 
102 |     return this.messageList
103 |   }
104 | 
105 |   async clearAll() {
106 |     this.messageList = [];
107 |     await fs.writeFile(
108 |       path.join(this.sessionPath, 'messages.json'),
109 |       '[]'
110 |     );
111 |   }
112 | }

