1 | /**
2 |  * SessionManager - 会话管理器
3 |  * 负责管理用户会话和三层存储架构
4 |  */
5 | import { Session, createSession } from "../domain/session";
6 | import { Message } from "../providers/base";
7 | import { CurrentSession } from "../domain/CurrentSession";
8 | import { ShortTermStore, SummaryMetadata } from "../domain/ShortTermStore";
9 | import { ILongTermStore } from "../domain/LongTermStore";
10 | import { ScopedLogger } from "../util/log";
11 | 
12 | const DEFAULT_COMPRESSION_THRESHOLD = 0.92; // 92% 触发压缩
13 | const KEEP_RECENT_COUNT = 6; // 压缩后保留最近 N 条消息（保留足够上下文）
14 | 
15 | export class SessionManager {
16 |     private logger: ScopedLogger;
17 |     private sessions = new Map<string, Session>();
18 |     private currentSessions = new Map<string, CurrentSession>();
19 |     private shortTermStores = new Map<string, ShortTermStore>();
20 |     private repository: ILongTermStore;
21 |     private loadedSessions = new Set<string>(); // 已加载历史记录的会话
22 | 
23 |     constructor(repository: ILongTermStore) {
24 |         this.logger = new ScopedLogger('SessionManager');
25 |         this.repository = repository;
26 |     }
27 | 
28 |     /**
29 |      * 创建新会话
30 |      */
31 |     async createSession(userId: string): Promise<Session> {
32 |         const session = createSession(userId);
33 |         this.sessions.set(session.id, session);
34 |         this.currentSessions.set(session.id, new CurrentSession());
35 |         this.shortTermStores.set(session.id, new ShortTermStore());
36 | 
37 |         // 持久化会话到数据库
38 |         try {
39 |             await this.repository.saveSession(session);
40 |         } catch (error) {
41 |             this.logger.error(`Failed to persist session ${session.id}`);
42 |         }
43 | 
44 |         this.logger.info(`Created session ${session.id} for user ${userId}`);
45 |         return session;
46 |     }
47 | 
48 |     /**
49 |      * 获取会话
