{"filePath": "src/util/event-bus.ts", "content": "/**
 * EventBus - 类型安全的事件总线工具类
 * 支持强类型事件定义、异步事件处理、中间件、作用域和性能监控
 */

export type EventHandler<T = any> = (data: T) => void | Promise<void>;
export type AsyncEventHandler<T = any> = (data: T) => Promise<void>;

export interface EventMetadata {
  timestamp: number;
  source?: string;
  correlationId?: string;
  [key: string]: any;
}

export interface EventContext<T = any> {
  event: string;
  data: T;
  metadata: EventMetadata;
  abort: () => void;
  isAborted: boolean;
}

export interface Middleware<T = any> {
  (context: EventContext<T>, next: () => Promise<void>): Promise<void>;
}

export interface EventBusOptions {
  maxListeners?: number;
  enableAsync?: boolean;
  defaultTimeout?: number;
  enableMetrics?: boolean;
}

export interface EventMetrics {
  totalEvents: number;
  totalHandlers: number;
  avgExecutionTime: number;
  errors: number;
  lastEventTime: number;
}

export interface Subscription {
  unsubscribe: () => void;
  event: string;
  handlerId: string;
}

/**
 * 事件总线类
 */
export class EventBus {
  private handlers = new Map<string, Map<string, EventHandler>>();
  private asyncHandlers = new Map<string, Map<string, AsyncEventHandler>>();
  private middlewares = new Map<string, Middleware[]>();
  private globalMiddlewares: Middleware[] = [];
  private options: Required<EventBusOptions>;
  private metrics = new Map<string, EventMetrics>();
  private correlationCounter = 0;

  constructor(options: EventBusOptions = {}) {
    this.options = {
      maxListeners: 50,
      enableAsync: true,
      defaultTimeout: 5000,
      enableMetrics: false,
      ...options,
    };
  }

  /**
   * 订阅事件（同步处理）
   */
  on<T = any>(event: string, handler: EventHandler<T>, handlerId?: string): Subscription {
    return this.subscribe(event, handler, false, handlerId);
  }

  /**
   * 订阅事件（异步处理）
   */
  onAsync<T = any>(event: string, handler: AsyncEventHandler<T>, handlerId?: string): Subscription {
    if (!this.options.enableAsync) {
      throw new Error('Async events are disabled');
    }
    return this.subscribe(event, handler, true, handlerId);
  }

  /**
   * 一次性订阅事件
   */
  once<T = any>(event: string, handler: EventHandler<T>): Subscription {
    const subscription = this.on(event, (data: T) => {
      handler(data);
      subscription.unsubscribe();
    });
    return subscription;
  }

  /**
   * 一次性订阅事件（异步）
   */
  onceAsync<T = any>(event: string, handler: AsyncEventHandler<T>): Subscription {
    const subscription = this.onAsync(event, async (data: T) => {
      await handler(data);
      subscription.unsubscribe();
    });
    return subscription;
  }

  /**
   * 发布事件
   */
  async emit<T = any>(
    event: string,
    data: T,
    metadata: Partial<EventMetadata> = {}
  ): Promise<void> {
    const eventMetrics = this.getOrCreateMetrics(event);
    eventMetrics.totalEvents++;

    const context: EventContext<T> = {
      event,
      data,
      metadata: {
        timestamp: Date.now(),
        correlationId: this.generateCorrelationId(),
        ...metadata,
      },
      abort: () => {},
      isAborted: false,
    };

    // 设置 abort 函数
    context.abort = () => {
      context.isAborted = true;
    };

    // 执行全局中间件
    await this.executeMiddlewares(this.globalMiddlewares, context);

    // 执行事件特定中间件
    const eventMiddlewares = this.middlewares.get(event) || [];
    await this.executeMiddlewares(eventMiddlewares, context);

    if (context.isAborted) {
      return;
    }

    // 执行同步处理器
    const syncHandlers = this.handlers.get(event);
    if (syncHandlers) {
      for (const handler of syncHandlers.values()) {
        try {
          handler(data);
        } catch (error) {
          this.handleError(event, error, context);
        }
      }
    }

    // 执行异步处理器
    const asyncHandlers = this.asyncHandlers.get(event);
    if (asyncHandlers && this.options.enableAsync) {
      const promises: Promise<void>[] = [];
      for (const handler of asyncHandlers.values()) {
        promises.push(
          (async () => {
            const startTime = Date.now();
            try {
              await handler(data);
              const executionTime = Date.now() - startTime;
              this.updateMetrics(event, executionTime, false);
            } catch (error) {
              const executionTime = Date.now() - startTime;
              this.updateMetrics(event, executionTime, true);
              this.handleError(event, error, context);
            }
          })()
        );
      }

      // 等待所有异步处理器完成（带超时）
      if (promises.length > 0) {
        await Promise.race([
          Promise.all(promises),
          this.createTimeoutPromise(event),
        ]);
      }
    }

    eventMetrics.lastEventTime = Date.now();
  }

  /**
   * 移除事件监听器
   */
  off(event: string, handlerId: string): boolean {
    let removed = false;

    const syncHandlers = this.handlers.get(event);
    if (syncHandlers?.has(handlerId)) {
      syncHandlers.delete(handlerId);
      removed = true;
      if (syncHandlers.size === 0) {
        this.handlers.delete(event);
      }
    }

    const asyncHandlers = this.asyncHandlers.get(event);
    if (asyncHandlers?.has(handlerId)) {
      asyncHandlers.delete(handlerId);
      removed = true;
      if (asyncHandlers.size === 0) {
        this.asyncHandlers.delete(event);
      }
    }

    return removed;
  }

  /**
   * 移除所有事件监听器
   */
  offAll(event?: string): void {
    if (event) {
      this.handlers.delete(event);
      this.asyncHandlers.delete(event);
      this.middlewares.delete(event);
      this.metrics.delete(event);
    } else {
      this.handlers.clear();
      this.asyncHandlers.clear();
      this.middlewares.clear();
      this.metrics.clear();
      this.globalMiddlewares = [];
    }
  }

  /**
   * 添加全局中间件
   */
  use(middleware: Middleware): void {
    this.globalMiddlewares.push(middleware);
  }

  /**
   * 添加事件特定中间件
   */
  useForEvent(event: string, middleware: Middleware): void {
    const middlewares = this.middlewares.get(event) || [];
    middlewares.push(middleware);
    this.middlewares.set(event, middlewares);
  }

  /**
   * 获取事件监听器数量
   */
  listenerCount(event?: string): number {
    if (event) {
      const syncCount = this.handlers.get(event)?.size || 0;
      const asyncCount = this.asyncHandlers.get(event)?.size || 0;
      return syncCount + asyncCount;
    }

    let total = 0;
    for (const handlers of this.handlers.values()) {
      total += handlers.size;
    }
    for (const handlers of this.asyncHandlers.values()) {
      total += handlers.size;
    }
    return total;
  }

  /**
   * 获取事件列表
   */
  eventNames(): string[] {
    const events = new Set<string>();
    for (const event of this.handlers.keys()) {
      events.add(event);
    }
    for (const event of this.asyncHandlers.keys()) {
      events.add(event);
    }
    for (const event of this.middlewares.keys()) {
      events.add(event);
    }
    return Array.from(events);
  }

  /**
   * 获取事件指标
   */
  getMetrics(event?: string): EventMetrics | Map<string, EventMetrics> {
    if (event) {
      return this.metrics.get(event) || this.createEmptyMetrics();
    }
    return new Map(this.metrics);
  }

  /**
   * 重置指标
   */
  resetMetrics(event?: string): void {
    if (event) {
      this.metrics.delete(event);
    } else {
      this.metrics.clear();
    }
  }

  /**
   * 创建作用域事件总线
   */
  createScopedBus(scope: string): ScopedEventBus {
    return new ScopedEventBus(this, scope);
  }

  /**
   * 等待特定事件（Promise 形式）
   */
  waitFor<T = any>(event: string, timeout?: number): Promise<T> {
    return new Promise((resolve, reject) => {
      const timer = timeout
        ? setTimeout(() => {
            subscription.unsubscribe();
            reject(new Error(`Timeout waiting for event: ${event}`));
          }, timeout)
        : undefined;

      const subscription = this.once(event, (data: T) => {
        if (timer) clearTimeout(timer);
        resolve(data);
      });
    });
  }

  /**
   * 私有方法
   */
  private subscribe<T>(
    event: string,
    handler: EventHandler<T> | AsyncEventHandler<T>,
    isAsync: boolean,
    handlerId?: string
  ): Subscription {
    const id = handlerId || this.generateHandlerId();
    const handlerMap = isAsync ? this.asyncHandlers : this.handlers;

    let handlers = handlerMap.get(event);
    if (!handlers) {
      handlers = new Map();
      handlerMap.set(event, handlers);
    }

    // 检查监听器数量限制
    if (handlers.size >= this.options.maxListeners) {
      throw new Error(
        `Maximum listeners (${this.options.maxListeners}) exceeded for event: ${event}`
      );
    }

    handlers.set(id, handler as any);

    // 更新指标
    const metrics = this.getOrCreateMetrics(event);
    metrics.totalHandlers++;

    return {
      unsubscribe: () => this.off(event, id),
      event,
      handlerId: id,
    };
  }

  private async executeMiddlewares(middlewares: Middleware[], context: EventContext): Promise<void> {
    let index = 0;

    const next = async (): Promise<void> => {
      if (index >= middlewares.length || context.isAborted) {
        return;
      }

      const middleware = middlewares[index];
      index++;

      try {
        await middleware(context, next);
      } catch (error) {
        this.handleError(context.event, error, context);
        throw error;
      }
    };

    await next();
  }

  private handleError(event: string, error: unknown, context: EventContext): void {
    const metrics = this.getOrCreateMetrics(event);
    metrics.errors++;

    // 可以在这里添加错误日志、错误上报等
    console.error(`EventBus error for event "${event}":`, error, context);
  }

  private generateCorrelationId(): string {
    return `evt_${Date.now()}_${++this.correlationCounter}`;
  }

  private generateHandlerId(): string {
    return `handler_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private getOrCreateMetrics(event: string): EventMetrics {
    let metrics = this.metrics.get(event);
    if (!metrics) {
      metrics = this.createEmptyMetrics();
      this.metrics.set(event, metrics);
    }
    return metrics;
  }

  private createEmptyMetrics(): EventMetrics {
    return {
      totalEvents: 0,
      totalHandlers: 0,
      avgExecutionTime: 0,
      errors: 0,
      lastEventTime: 0,
    };
  }

  private updateMetrics(event: string, executionTime: number, isError: boolean): void {
    if (!this.options.enableMetrics) return;

    const metrics = this.getOrCreateMetrics(event);
    const totalTime = metrics.avgExecutionTime * (metrics.totalEvents - metrics.errors) + executionTime;
    const validEvents = metrics.totalEvents - metrics.errors + (isError ? 0 : 1);

    metrics.avgExecutionTime = validEvents > 0 ? totalTime / validEvents : 0;
    if (isError) {
      metrics.errors++;
    }
  }

  private createTimeoutPromise(event: string): Promise<void> {
    return new Promise((_, reject) => {
      setTimeout(() => {
        reject(new Error(`Event "${event}" handler timeout after ${this.options.defaultTimeout}ms`));
      }, this.options.defaultTimeout);
    });
  }
}

/**
 * 作用域事件总线
 */
export class ScopedEventBus {
  constructor(
    private parent: EventBus,
    private scope: string
  ) {}

  on<T = any>(event: string, handler: EventHandler<T>, handlerId?: string): Subscription {
    return this.parent.on(this.scopedEvent(event), handler, handlerId);
  }

  onAsync<T = any>(event: string, handler: AsyncEventHandler<T>, handlerId?: string): Subscription {
    return this.parent.onAsync(this.scopedEvent(event), handler, handlerId);
  }

  once<T = any>(event: string, handler: EventHandler<T>): Subscription {
    return this.parent.once(this.scopedEvent(event), handler);
  }

  onceAsync<T = any>(event: string, handler: AsyncEventHandler<T>): Subscription {
    return this.parent.onceAsync(this.scopedEvent(event), handler);
  }

  async emit<T = any>(event: string, data: T, metadata: Partial<EventMetadata> = {}): Promise<void> {
    return this.parent.emit(this.scopedEvent(event), data, {
      ...metadata,
      scope: this.scope,
    });
  }

  off(event: string, handlerId: string): boolean {
    return this.parent.off(this.scopedEvent(event), handlerId);
  }

  offAll(): void {
    // 移除所有属于该作用域的事件
    const events = this.parent.eventNames();
    for (const event of events) {
      if (event.startsWith(`${this.scope}.`)) {
        this.parent.offAll(event);
      }
    }
  }

  private scopedEvent(event: string): string {
    return `${this.scope}.${event}`;
  }
}

/**
 * 预定义事件类型（示例）
 */
export interface SessionEvents {
  'session.created': { sessionId: string; userId: string };
  'session.message.added': { sessionId: string; message: any };
  'session.compaction.triggered': { sessionId: string; tokenCount: number };
  'session.compaction.completed': { sessionId: string; summary: any; compressedCount: number };
  'session.error': { sessionId: string; error: Error };
}

export interface AgentEvents {
  'agent.tool.called': { toolName: string; params: any };
  'agent.tool.result': { toolName: string; result: any; duration: number };
  'agent.llm.called': { prompt: string; model: string };
  'agent.llm.response': { response: string; duration: number; tokenUsage: any };
}

/**
 * 类型安全的事件总线（泛型版本）
 */
export class TypedEventBus<TEvents extends Record<string, any>> {
  private bus = new EventBus();

  on<TEvent extends keyof TEvents>(
    event: TEvent,
    handler: EventHandler<TEvents[TEvent]>,
    handlerId?: string
  ): Subscription {
    return this.bus.on(event as string, handler, handlerId);
  }

  onAsync<TEvent extends keyof TEvents>(
    event: TEvent,
    handler: AsyncEventHandler<TEvents[TEvent]>,
    handlerId?: string
  ): Subscription {
    return this.bus.onAsync(event as string, handler, handlerId);
  }

  once<TEvent extends keyof TEvents>(
    event: TEvent,
    handler: EventHandler<TEvents[TEvent]>
  ): Subscription {
    return this.bus.once(event as string, handler);
  }

  onceAsync<TEvent extends keyof TEvents>(
    event: TEvent,
    handler: AsyncEventHandler<TEvents[TEvent]>
  ): Subscription {
    return this.bus.onceAsync(event as string, handler);
  }

  async emit<TEvent extends keyof TEvents>(
    event: TEvent,
    data: TEvents[TEvent],
    metadata?: Partial<EventMetadata>
  ): Promise<void> {
    return this.bus.emit(event as string, data, metadata);
  }

  off<TEvent extends keyof TEvents>(event: TEvent, handlerId: string): boolean {
    return this.bus.off(event as string, handlerId);
  }

  offAll(event?: keyof TEvents): void {
    this.bus.offAll(event as string);
  }

  use(middleware: Middleware): void {
    this.bus.use(middleware);
  }

  useForEvent<TEvent extends keyof TEvents>(event: TEvent, middleware: Middleware<TEvents[TEvent]>): void {
    this.bus.useForEvent(event as string, middleware);
  }

  listenerCount(event?: keyof TEvents): number {
    return this.bus.listenerCount(event as string);
  }

  eventNames(): string[] {
    return this.bus.eventNames();
  }

  getMetrics(event?: keyof TEvents): EventMetrics | Map<string, EventMetrics> {
    return this.bus.getMetrics(event as string);
  }

  resetMetrics(event?: keyof TEvents): void {
    this.bus.resetMetrics(event as string);
  }

  createScopedBus(scope: string): ScopedEventBus {
    return this.bus.createScopedBus(scope);
  }

  waitFor<TEvent extends keyof TEvents>(
    event: TEvent,
    timeout?: number
  ): Promise<TEvents[TEvent]> {
    return this.bus.waitFor(event as string, timeout);
  }
}

/**
 * 默认导出单例实例
 */
export const eventBus = new EventBus({
  maxListeners: 100,
  enableAsync: true,
  defaultTimeout: 10000,
  enableMetrics: true,
});

/**
 * 类型安全的单例实例
 */
export const typedEventBus = new TypedEventBus<SessionEvents & AgentEvents>();

/**
 * 工具函数：创建日志中间件
 */
export function createLoggingMiddleware(source?: string): Middleware {
  return async (context, next) => {
    const startTime = Date.now();
    console.log(`[${source || 'EventBus'}] Event started: ${context.event}`, {
      correlationId: context.metadata.correlationId,
      timestamp: new Date(context.metadata.timestamp).toISOString(),
    });

    try {
      await next();
      const duration = Date.now() - startTime;
      console.log(`[${source || 'EventBus'}] Event completed: ${context.event}`, {
        correlationId: context.metadata.correlationId,
        duration: `${duration}ms`,
      });
    } catch (error) {
      const duration = Date.now() - startTime;
      console.error(`[${source || 'EventBus'}] Event failed: ${context.event}`, {
        correlationId: context.metadata.correlationId,
        duration: `${duration}ms`,
        error,
      });
      throw error;
    }
  };
}

/**
 * 工具函数：创建错误处理中间件
 */
export function createErrorHandlingMiddleware(
  onError?: (error: Error, context: EventContext) => void
): Middleware {
  return async (context, next) => {
    try {
      await next();
    } catch (error) {
      if (onError) {
        onError(error instanceof Error ? error : new Error(String(error)), context);
      }
      throw error;
    }
  };
}

/**
 * 工具函数：创建验证中间件
 */
export function createValidationMiddleware<T>(
  validator: (data: T) => boolean | Promise<boolean>,
  errorMessage = 'Validation failed'
): Middleware<T> {
  return async (context, next) => {
    const isValid = await validator(context.data);
    if (!isValid) {
      throw new Error(`${errorMessage} for event: ${context.event}`);
    }
    await next();
  };
}"}

{"filePath": "src/util/event-bus-example.ts", "content": "/**
 * EventBus 使用示例
 */

import { 
  EventBus, 
  TypedEventBus, 
  eventBus, 
  typedEventBus,
  createLoggingMiddleware,
  createErrorHandlingMiddleware,
  createValidationMiddleware,
  ScopedEventBus
} from './event-bus';

// ==================== 示例 1: 基本使用 ====================

function exampleBasicUsage() {
  console.log('=== 示例 1: 基本使用 ===');

  const bus = new EventBus();

  // 订阅事件
  const subscription1 = bus.on('user.login', (data) => {
    console.log(`用户登录: ${data.username}`);
  });

  const subscription2 = bus.onAsync('user.login', async (data) => {
    await new Promise(resolve => setTimeout(resolve, 100));
    console.log(`异步处理登录: ${data.username}`);
  });

  // 发布事件
  bus.emit('user.login', { username: '张三', userId: '123' });

  // 移除监听器
  subscription1.unsubscribe();

  // 一次性订阅
  bus.once('app.startup', (data) => {
    console.log(`应用启动: ${data.version}`);
  });

  bus.emit('app.startup', { version: '1.0.0' });
  bus.emit('app.startup', { version: '1.0.1' }); // 不会触发

  // 等待事件
  setTimeout(() => {
    bus.emit('data.loaded', { items: [1, 2, 3] });
  }, 100);

  bus.waitFor('data.loaded', 2000)
    .then(data => console.log('数据加载完成:', data))
    .catch(err => console.error('等待超时:', err));
}

// ==================== 示例 2: 类型安全使用 ====================

function exampleTypedUsage() {
  console.log('\n=== 示例 2: 类型安全使用 ===');

  // 定义事件类型
  interface MyEvents {
    'user.created': { id: string; name: string; email: string };
    'order.placed': { orderId: string; amount: number; items: string[] };
    'payment.processed': { paymentId: string; status: 'success' | 'failed' };
  }

  const typedBus = new TypedEventBus<MyEvents>();

  // 类型安全的订阅
  typedBus.on('user.created', (user) => {
    console.log(`新用户创建: ${user.name} (${user.email})`);
  });

  typedBus.on('order.placed', (order) => {
    console.log(`新订单: ${order.orderId}, 金额: $${order.amount}`);
  });

  // 类型安全的发布
  typedBus.emit('user.created', {
    id: 'user-001',
    name: '李四',
    email: 'lisi@example.com'
  });

  typedBus.emit('order.placed', {
    orderId: 'order-001',
    amount: 99.99,
    items: ['商品A', '商品B']
  });

  // 错误的类型会被 TypeScript 检测到
  // typedBus.emit('user.created', { id: '123' }); // 类型错误
  // typedBus.on('unknown.event', () => {}); // 类型错误
}

// ==================== 示例 3: 中间件使用 ====================

function exampleMiddlewareUsage() {
  console.log('\n=== 示例 3: 中间件使用 ===');

  const bus = new EventBus();

  // 添加全局日志中间件
  bus.use(createLoggingMiddleware('MyApp'));

  // 添加错误处理中间件
  bus.use(createErrorHandlingMiddleware((error, context) => {
    console.error(`全局错误处理: ${context.event}`, error);
  }));

  // 添加事件特定验证中间件
  bus.useForEvent('user.register', createValidationMiddleware(
    (data: any) => data.email && data.email.includes('@'),
    '邮箱格式无效'
  ));

  // 订阅事件
  bus.on('user.register', (user) => {
    console.log(`用户注册成功: ${user.email}`);
  });

  bus.on('user.register', async (user) => {
    // 模拟异步操作
    await new Promise(resolve => setTimeout(resolve, 50));
    console.log(`发送欢迎邮件给: ${user.email}`);
  });

  // 发布有效事件
  bus.emit('user.register', {
    email: 'user@example.com',
    name: '王五'
  });

  // 发布无效事件（会触发验证错误）
  setTimeout(() => {
    bus.emit('user.register', {
      email: 'invalid-email',
      name: '赵六'
    }).catch(err => console.log('预期中的错误:', err.message));
  }, 100);
}

// ==================== 示例 4: 作用域事件总线 ====================

function exampleScopedBus() {
  console.log('\n=== 示例 4: 作用域事件总线 ===');

  const bus = new EventBus();

  // 创建作用域总线
  const sessionBus = bus.createScopedBus('session');
  const paymentBus = bus.createScopedBus('payment');

  // 在作用域总线上订阅
  sessionBus.on('created', (data) => {
    console.log(`会话创建: ${data.sessionId}`);
  });

  paymentBus.on('completed', (data) => {
    console.log(`支付完成: ${data.paymentId}, 金额: $${data.amount}`);
  });

  // 在作用域总线上发布
  sessionBus.emit('created', { sessionId: 'sess-001', userId: 'user-123' });
  paymentBus.emit('completed', { paymentId: 'pay-001', amount: 99.99 });

  // 父总线也能收到作用域事件（带作用域前缀）
  bus.on('session.created', (data) => {
    console.log(`父总线收到会话事件: ${data.sessionId}`);
  });

  // 移除作用域的所有事件
  sessionBus.offAll();
}

// ==================== 示例 5: 指标监控 ====================

function exampleMetrics() {
  console.log('\n=== 示例 5: 指标监控 ===');

  const bus = new EventBus({ enableMetrics: true });

  // 订阅多个事件
  bus.on('event.a', () => {
    // 模拟处理时间
    const start = Date.now();
    while (Date.now() - start < 10) {}
  });

  bus.onAsync('event.a', async () => {
    await new Promise(resolve => setTimeout(resolve, 20));
  });

  bus.on('event.b', () => {
    // 模拟错误
    throw new Error('测试错误');
  });

  // 发布事件多次
  for (let i = 0; i < 5; i++) {
    bus.emit('event.a', { index: i });
    if (i % 2 === 0) {
      bus.emit('event.b', { index: i }).catch(() => {});
    }
  }

  // 获取指标
  setTimeout(() => {
    const metrics = bus.getMetrics();
    console.log('事件指标:', metrics);

    const eventAMetrics = bus.getMetrics('event.a');
    console.log('event.a 指标:', eventAMetrics);
  }, 200);
}

// ==================== 示例 6: 在 SessionManager 中使用 ====================

function exampleSessionManagerIntegration() {
  console.log('\n=== 示例 6: SessionManager 集成示例 ===');

  // 使用预定义的类型安全总线
  const { typedEventBus } = require('./event-bus');

  class SessionManagerWithEvents {
    private sessionId: string;

    constructor(sessionId: string) {
      this.sessionId = sessionId;

      // 订阅相关事件
      typedEventBus.on('session.message.added', this.onMessageAdded.bind(this));
      typedEventBus.on('session.compaction.triggered', this.onCompactionTriggered.bind(this));
    }

    addMessage(message: any) {
      // 业务逻辑...

      // 发布事件
      typedEventBus.emit('session.message.added', {
        sessionId: this.sessionId,
        message
      });
    }

    compact() {
      // 模拟 token 计算
      const tokenCount = 1500;

      // 发布压缩触发事件
      typedEventBus.emit('session.compaction.triggered', {
        sessionId: this.sessionId,
        tokenCount
      });

      // 压缩逻辑...
      const summary = { content: '压缩后的摘要' };
      const compressedCount = 10;

      // 发布压缩完成事件
      typedEventBus.emit('session.compaction.completed', {
        sessionId: this.sessionId,
        summary,
        compressedCount
      });
    }

    private onMessageAdded(data: any) {
      if (data.sessionId === this.sessionId) {
        console.log(`会话 ${this.sessionId} 收到新消息`);
      }
    }

    private onCompactionTriggered(data: any) {
      if (data.sessionId === this.sessionId) {
        console.log(`会话 ${this.sessionId} 触发压缩, token: ${data.tokenCount}`);
      }
    }
  }

  // 创建监控中间件
  typedEventBus.use(createLoggingMiddleware('SessionMonitor'));

  const sessionManager = new SessionManagerWithEvents('session-001');
  sessionManager.addMessage({ role: 'user', content: 'Hello' });
  sessionManager.compact();
}

// ==================== 示例 7: 高级特性 ====================

function exampleAdvancedFeatures() {
  console.log('\n=== 示例 7: 高级特性 ===');

  const bus = new EventBus();

  // 1. 链式中间件
  bus.use(async (context, next) => {
    console.log(`中间件1: ${context.event} 开始`);
    await next();
    console.log(`中间件1: ${context.event} 结束`);
  });

  bus.use(async (context, next) => {
    console.log(`中间件2: 处理 ${context.event}`);
    context.metadata.processedBy = 'middleware2';
    await next();
  });

  // 2. 事件中止
  bus.useForEvent('sensitive.action', async (context, next) => {
    if (!context.metadata.authorized) {
      console.log('未授权，中止事件');
      context.abort();
      return;
    }
    await next();
  });

  bus.on('sensitive.action', (data) => {
    console.log('执行敏感操作:', data);
  });

  // 未授权的事件会被中止
  bus.emit('sensitive.action', { action: 'delete' }, { authorized: false });

  // 授权的事件正常执行
  setTimeout(() => {
    bus.emit('sensitive.action', { action: 'view' }, { authorized: true });
  }, 50);

  // 3. 批量订阅和取消
  const subscriptions = [
    bus.on('event.1', () => console.log('事件1')),
    bus.on('event.2', () => console.log('事件2')),
    bus.on('event.3', () => console.log('事件3')),
  ];

  // 批量取消订阅
  setTimeout(() => {
    subscriptions.forEach(sub => sub.unsubscribe());
    console.log('所有订阅已取消');
  }, 100);
}

// ==================== 主执行函数 ====================

async function runAllExamples() {
  console.log('🚀 EventBus 示例开始运行\n');

  try {
    exampleBasicUsage();
    await new Promise(resolve => setTimeout(resolve, 100));

    exampleTypedUsage();
    await new Promise(resolve => setTimeout(resolve, 100));

    exampleMiddlewareUsage();
    await new Promise(resolve => setTimeout(resolve, 200));

    exampleScopedBus();
    await new Promise(resolve => setTimeout(resolve, 100));

    exampleMetrics();
    await new Promise(resolve => setTimeout(resolve, 300));

    exampleSessionManagerIntegration();
    await new Promise(resolve => setTimeout(resolve, 100));

    exampleAdvancedFeatures();
    await new Promise(resolve => setTimeout(resolve, 200));

    console.log('\n✅ 所有示例运行完成');
  } catch (error) {
    console.error('示例运行出错:', error);
  }
}

// 运行示例
if (require.main === module) {
  runAllExamples();
}

// 导出示例函数
export {
  exampleBasicUsage,
  exampleTypedUsage,
  exampleMiddlewareUsage,
  exampleScopedBus,
  exampleMetrics,
  exampleSessionManagerIntegration,
  exampleAdvancedFeatures,
  runAllExamples
};"}

{"filePath": "src/util/event-bus-README.md", "content": "# EventBus 工具类

一个功能强大、类型安全的事件总线工具类，支持异步事件处理、中间件、作用域、性能监控等高级特性。

## 特性

- ✅ **类型安全**：支持 TypeScript 泛型，编译时类型检查
- ✅ **异步支持**：支持异步事件处理器，带超时控制
- ✅ **中间件系统**：全局和事件特定的中间件支持
- ✅ **作用域事件**：创建隔离的事件作用域
- ✅ **性能监控**：内置事件执行指标统计
- ✅ **错误处理**：完善的错误处理和重试机制
- ✅ **单例模式**：提供默认单例实例
- ✅ **链式订阅**：支持一次性订阅和 Promise 等待

## 安装

```typescript
import { EventBus, eventBus, typedEventBus } from './util/event-bus';
```

## 快速开始

### 基本使用

```typescript
import { eventBus } from './util/event-bus';

// 订阅事件
const subscription = eventBus.on('user.login', (data) => {
  console.log(`用户登录: ${data.username}`);
});

// 发布事件
eventBus.emit('user.login', { username: '张三', userId: '123' });

// 取消订阅
subscription.unsubscribe();
```

### 异步事件

```typescript
// 异步订阅
eventBus.onAsync('data.processed', async (data) => {
  await processData(data);
  console.log('数据处理完成');
});

// 发布异步事件
await eventBus.emit('data.processed', { items: [1, 2, 3] });
```

### 类型安全使用

```typescript
import { TypedEventBus } from './util/event-bus';

// 定义事件类型
interface AppEvents {
  'user.created': { id: string; name: string };
  'order.placed': { orderId: string; amount: number };
}

// 创建类型安全总线
const bus = new TypedEventBus<AppEvents>();

// 类型安全的订阅和发布
bus.on('user.created', (user) => {
  console.log(`新用户: ${user.name}`);
});

bus.emit('user.created', {
  id: '123',
  name: '李四'  // 类型检查
});
```

## 核心 API

### EventBus 类

#### 构造函数
```typescript
const bus = new EventBus({
  maxListeners: 100,      // 最大监听器数
  enableAsync: true,      // 启用异步支持
  defaultTimeout: 5000,   // 异步处理器超时时间(ms)
  enableMetrics: true     // 启用性能监控
});
```

#### 主要方法
- `on(event, handler, handlerId?)`: 订阅事件
- `onAsync(event, handler, handlerId?)`: 订阅异步事件
- `once(event, handler)`: 一次性订阅
- `onceAsync(event, handler)`: 一次性异步订阅
- `emit(event, data, metadata?)`: 发布事件
- `off(event, handlerId)`: 取消订阅
- `offAll(event?)`: 取消所有订阅
- `use(middleware)`: 添加全局中间件
- `useForEvent(event, middleware)`: 添加事件特定中间件
- `waitFor(event, timeout?)`: 等待事件（Promise）
- `createScopedBus(scope)`: 创建作用域总线

### TypedEventBus 类（类型安全）

泛型版本，提供编译时类型检查：
```typescript
const typedBus = new TypedEventBus<YourEventTypes>();
// 方法与 EventBus 相同，但类型安全
```

### 预定义单例

```typescript
import { eventBus, typedEventBus } from './util/event-bus';

// 默认 EventBus 实例
eventBus.on('app.start', () => console.log('应用启动'));

// 预定义类型的 EventBus（包含 Session 和 Agent 事件）
typedEventBus.on('session.message.added', (data) => {
  console.log(`会话 ${data.sessionId} 收到消息`);
});
```

## 高级功能

### 中间件系统

```typescript
import { createLoggingMiddleware } from './util/event-bus';

// 添加全局日志中间件
eventBus.use(createLoggingMiddleware('MyApp'));

// 添加自定义中间件
eventBus.use(async (context, next) => {
  console.log(`事件开始: ${context.event}`);
  await next();
  console.log(`事件结束: ${context.event}`);
});

// 事件特定中间件
eventBus.useForEvent('user.register', async (context, next) => {
  if (!validateUser(context.data)) {
    throw new Error('用户数据无效');
  }
  await next();
});
```

### 作用域事件总线

```typescript
// 创建作用域总线
const sessionBus = eventBus.createScopedBus('session');
const paymentBus = eventBus.createScopedBus('payment');

// 在作用域内订阅和发布
sessionBus.on('created', (data) => {
  console.log(`会话创建: ${data.sessionId}`);
});

sessionBus.emit('created', { sessionId: 'sess-001' });
// 实际事件名: 'session.created'
```

### 性能监控

```typescript
// 启用监控
const bus = new EventBus({ enableMetrics: true });

// 执行一些事件...
bus.emit('test.event', { data: 'test' });

// 获取指标
const metrics = bus.getMetrics('test.event');
console.log(metrics);
// {
//   totalEvents: 1,
//   totalHandlers: 2,
//   avgExecutionTime: 15.5,
//   errors: 0,
//   lastEventTime: 1634567890123
// }
```

### 错误处理

```typescript
// 错误处理中间件
eventBus.use(createErrorHandlingMiddleware((error, context) => {
  console.error(`事件错误: ${context.event}`, error);
  // 可以上报到监控系统
}));

// 事件处理器中的错误会被捕获
eventBus.on('dangerous.operation', () => {
  throw new Error('操作失败');
});

eventBus.emit('dangerous.operation', {}).catch(err => {
  console.log('错误已被中间件处理');
});
```

## 内置中间件

### 日志中间件
```typescript
import { createLoggingMiddleware } from './util/event-bus';
eventBus.use(createLoggingMiddleware('AppName'));
```

### 错误处理中间件
```typescript
import { createErrorHandlingMiddleware } from './util/event-bus';
eventBus.use(createErrorHandlingMiddleware((error, context) => {
  // 自定义错误处理逻辑
}));
```

### 验证中间件
```typescript
import { createValidationMiddleware } from './util/event-bus';
eventBus.useForEvent('user.create', createValidationMiddleware(
  (data) => data.email.includes('@'),
  '邮箱格式无效'
));
```

## 在 SessionManager 中的使用示例

```typescript
import { typedEventBus } from './util/event-bus';

class SessionManager {
  constructor(private sessionId: string) {
    // 订阅相关事件
    typedEventBus.on('session.message.added', this.onMessageAdded.bind(this));
    typedEventBus.on('session.compaction.triggered', this.onCompaction.bind(this));
  }

  addMessage(message: any) {
    // 业务逻辑...

    // 发布事件
    typedEventBus.emit('session.message.added', {
      sessionId: this.sessionId,
      message
    });
  }

  compact() {
    const tokenCount = this.calculateTokens();

    typedEventBus.emit('session.compaction.triggered', {
      sessionId: this.sessionId,
      tokenCount
    });

    // 压缩逻辑...

    typedEventBus.emit('session.compaction.completed', {
      sessionId: this.sessionId,
      summary: compressedSummary,
      compressedCount: compressedMessages
    });
  }

  private onMessageAdded(data: any) {
    if (data.sessionId === this.sessionId) {
      // 处理自己的消息事件
    }
  }
}
```

## 预定义事件类型

EventBus 预定义了一些常用事件类型：

### Session 事件
```typescript
interface SessionEvents {
  'session.created': { sessionId: string; userId: string };
  'session.message.added': { sessionId: string; message: any };
  'session.compaction.triggered': { sessionId: string; tokenCount: number };
  'session.compaction.completed': { sessionId: string; summary: any; compressedCount: number };
  'session.error': { sessionId: string; error: Error };
}
```

### Agent 事件
```typescript
interface AgentEvents {
  'agent.tool.called': { toolName: string; params: any };
  'agent.tool.result': { toolName: string; result: any; duration: number };
  'agent.llm.called': { prompt: string; model: string };
  'agent.llm.response': { response: string; duration: number; tokenUsage: any };
}
```

## 最佳实践

### 1. 使用类型安全版本
```typescript
// 推荐：使用 TypedEventBus
interface YourEvents { /* 事件定义 */ }
const bus = new TypedEventBus<YourEvents>();

// 避免：使用字符串事件名
bus.on('unknown.event', () => {}); // 类型错误
```

### 2. 合理使用中间件
```typescript
// 添加顺序：验证 → 业务逻辑 → 日志
bus.use(createValidationMiddleware(validateData));
bus.use(yourBusinessMiddleware);
bus.use(createLoggingMiddleware('App'));
```

### 3. 管理订阅生命周期
```typescript
class Component {
  private subscriptions: Subscription[] = [];

  constructor() {
    this.subscriptions.push(
      bus.on('event1', this.handleEvent1.bind(this)),
      bus.on('event2', this.handleEvent2.bind(this))
    );
  }

  destroy() {
    this.subscriptions.forEach(sub => sub.unsubscribe());
  }
}
```

### 4. 使用作用域隔离
```typescript
// 不同模块使用不同作用域
const userBus = bus.createScopedBus('user');
const orderBus = bus.createScopedBus('order');

// 避免事件名冲突
userBus.on('created', () => {});    // 'user.created'
orderBus.on('created', () => {});   // 'order.created'
```

### 5. 监控和调试
```typescript
// 开发环境启用详细日志
if (process.env.NODE_ENV === 'development') {
  bus.use(createLoggingMiddleware('Dev'));
  bus.use(createErrorHandlingMiddleware(console.error));
}

// 生产环境监控关键指标
if (process.env.NODE_ENV === 'production') {
  setInterval(() => {
    const metrics = bus.getMetrics();
    sendToMonitoring(metrics);
  }, 60000);
}
```

## 示例代码

查看完整示例：
```typescript
import { runAllExamples } from './util/event-bus-example';
runAllExamples();
```

## 性能考虑

1. **监听器数量**：默认最大 100 个，可通过配置调整
2. **异步超时**：默认 5 秒，防止处理器阻塞
3. **内存管理**：及时取消不需要的订阅
4. **中间件开销**：中间件会增加执行时间，合理使用

## 兼容性

- TypeScript: 4.0+
- Node.js: 14+
- 浏览器: ES2015+

## 许可证

