import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import {
  EventBus,
  TypedEventBus,
  eventBus,
  typedEventBus,
  createLoggingMiddleware,
  createErrorHandlingMiddleware,
  createValidationMiddleware,
  ScopedEventBus,
